			towerDamage.m_sourceID = getObject()->getID();
			towerDamage.m_damageType = ((const Rva00263895Member *)damageInfo)->m_damageType;
			towerDamage.m_deathType = ((const Rva00263895Member *)damageInfo)->m_deathType;
